-- Enforce canonical role/action policy before existing scoped business logic.
-- Existing implementations are renamed and retained; wrappers preserve signatures and defaults.

INSERT INTO platform_identity.action_catalog(object_type,action,display_name,data_class,consequence,data_action)
VALUES('capacity','request','Request project capacity','delivery','normal','write')
ON CONFLICT (object_type,action) DO UPDATE SET display_name=EXCLUDED.display_name,data_class=EXCLUDED.data_class,consequence=EXCLUDED.consequence,data_action=EXCLUDED.data_action,active=1;
INSERT INTO platform_identity.role_action_policy(role_key,object_type,action,authority_mode,notes)
SELECT r.role_key,'capacity','request','deny','Default deny; explicitly overridden below.' FROM platform_identity.role_catalog r WHERE r.active=1
ON CONFLICT (role_key,object_type,action) DO NOTHING;
UPDATE platform_identity.role_action_policy SET authority_mode='allow',condition_code=NULL,notes='Project management may request capacity; allocation remains Resource Manager authority.'
WHERE role_key IN ('project-manager','project-director') AND object_type='capacity' AND action='request';

CREATE OR REPLACE FUNCTION goliath_api.require_capability(p_assignment_id text,p_object_type text,p_action text)
RETURNS text
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public','platform_identity','auth','goliath_api'
AS $function$
DECLARE v_mode text;
BEGIN
  v_mode:=goliath_api.capability_mode(p_assignment_id,p_object_type,p_action);
  IF v_mode='deny' THEN
    RAISE EXCEPTION 'This responsibility is not authorised for %.%.',p_object_type,p_action USING ERRCODE='42501';
  END IF;
  RETURN v_mode;
END
$function$;
REVOKE ALL ON FUNCTION goliath_api.require_capability(text,text,text) FROM PUBLIC, authenticated, goliath_web_anon;

