CREATE OR REPLACE FUNCTION goliath_api.confirm_commitment_candidate(p_assignment_id text,p_candidate_id text,p_workstream_id text,p_type text,p_owner_id text,p_committed_date text,p_committed_date_kind text,p_acceptance_criteria text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'commitment','confirm-candidate'); RETURN goliath_api._policy_confirm_commitment_candidate(p_assignment_id,p_candidate_id,p_workstream_id,p_type,p_owner_id,p_committed_date,p_committed_date_kind,p_acceptance_criteria); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.activate_commitment(p_assignment_id text,p_commitment_id text,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'commitment','activate'); RETURN goliath_api._policy_activate_commitment(p_assignment_id,p_commitment_id,p_reason); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.create_decision(p_assignment_id text,p_project_id text,p_question text,p_decision_owner_id text,p_needed_by text,p_impact_if_late text,p_impact_weight integer DEFAULT 1,p_options jsonb DEFAULT '[]'::jsonb,p_recommendation text DEFAULT NULL,p_recommendation_origin text DEFAULT 'human',p_commitment_ids jsonb DEFAULT '[]'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'decision','create'); RETURN goliath_api._policy_create_decision(p_assignment_id,p_project_id,p_question,p_decision_owner_id,p_needed_by,p_impact_if_late,p_impact_weight,p_options,p_recommendation,p_recommendation_origin,p_commitment_ids); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.resolve_decision(p_assignment_id text,p_decision_id text,p_state text,p_choice text,p_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'decision','resolve'); RETURN goliath_api._policy_resolve_decision(p_assignment_id,p_decision_id,p_state,p_choice,p_reason); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.create_commitment_dependency(p_assignment_id text,p_consumer_commitment_id text,p_provider_type text,p_provider_ref text,p_needed_by text,p_acceptance_criteria text,p_provider_commitment_id text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'dependency','create'); RETURN goliath_api._policy_create_commitment_dependency(p_assignment_id,p_consumer_commitment_id,p_provider_type,p_provider_ref,p_needed_by,p_acceptance_criteria,p_provider_commitment_id); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.acknowledge_commitment_dependency(p_assignment_id text,p_dependency_id text,p_side text,p_promised_date text DEFAULT NULL,p_reason text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'dependency','acknowledge'); RETURN goliath_api._policy_acknowledge_commitment_dependency(p_assignment_id,p_dependency_id,p_side,p_promised_date,p_reason); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.create_requirement(p_assignment_id text,p_project_id text,p_title text,p_master_system text,p_source_ref text,p_source_version text,p_verbatim_text text,p_owner_id text,p_priority text DEFAULT 'medium') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'requirement','create'); RETURN goliath_api._policy_create_requirement(p_assignment_id,p_project_id,p_title,p_master_system,p_source_ref,p_source_version,p_verbatim_text,p_owner_id,p_priority); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.create_raid_item(p_assignment_id text,p_project_id text,p_item_type text,p_title text,p_description text,p_owner_id text,p_likelihood_rating integer DEFAULT NULL,p_impact_rating integer DEFAULT NULL,p_response text DEFAULT NULL,p_trigger_type text DEFAULT NULL,p_trigger_ref text DEFAULT NULL,p_validation_date text DEFAULT NULL,p_commitment_ids jsonb DEFAULT '[]'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ DECLARE v_action text; BEGIN v_action:=CASE p_item_type WHEN 'risk' THEN 'create-risk' WHEN 'issue' THEN 'create-issue' WHEN 'assumption' THEN 'create-assumption' ELSE NULL END; IF v_action IS NULL THEN RAISE EXCEPTION 'RAID type must be risk, issue or assumption.' USING ERRCODE='22023'; END IF; PERFORM goliath_api.require_capability(p_assignment_id,'raid',v_action); RETURN goliath_api._policy_create_raid_item(p_assignment_id,p_project_id,p_item_type,p_title,p_description,p_owner_id,p_likelihood_rating,p_impact_rating,p_response,p_trigger_type,p_trigger_ref,p_validation_date,p_commitment_ids); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.submit_initial_baseline(p_assignment_id text,p_project_id text,p_approver_user_id text,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'baseline','submit'); RETURN goliath_api._policy_submit_initial_baseline(p_assignment_id,p_project_id,p_approver_user_id,p_reason); END $function$;
CREATE OR REPLACE FUNCTION goliath_api.finalize_initial_baseline(p_assignment_id text,p_project_id text,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','platform_identity','auth','goliath_api' AS $function$ BEGIN PERFORM goliath_api.require_capability(p_assignment_id,'baseline','finalize'); RETURN goliath_api._policy_finalize_initial_baseline(p_assignment_id,p_project_id,p_reason); END $function$;
